31	export class AboutSceneRig {
32	  compose(state: AboutSceneState): SceneFromState {
33	    return {
34	      camera: {
35	        position: { ...state.camera.position },
36	        fov: state.camera.fov,
37	      },
38	      cameraTarget: {
39	        position: { ...state.camera.target },
40	      },
41	      [aboutBackgroundId]: state.background,
42	      [earthId]: state.earth,
43	      [rocketId]: state.rocket,
44	      [jetEngineId]: {
45	        position: { ...state.jetEngine.position },
46	        rotation: { ...state.jetEngine.rotation },
47	        scale: { ...state.jetEngine.scale },
48	        visible: state.jetEngine.visible,
49	      },
50	      [astronautId]: state.astronaut,
51	      [terrianId]: state.terrian,
52	    } as unknown as SceneFromState;
53	  }
54	
55	  apply(engine: Engine, state: AboutSceneState): void {
56	    engine.setState(this.compose(state));
57	    const camera = engine.getCamera();
58	    camera.lookAt(engine.getCameraTarget().position);
59	    this._applyLight(engine, state.light);
60	    this._applyRocket(engine, state.rocket);
61	    this._applyJetEngine(engine, state.jetEngine);
62	  }
63	
64	  read(engine: Engine): AboutSceneState {
65	    const camera = engine.getCamera();
66	    const target = engine.getCameraTarget();
67	    return {
68	      camera: {
69	        position: {
70	          x: this._toFinite(camera.position.x, 0),
71	          y: this._toFinite(camera.position.y, 0),
72	          z: this._toFinite(camera.position.z, 18),
73	        },
74	        target: {
75	          x: this._toFinite(target.position.x, 0),
76	          y: this._toFinite(target.position.y, 0),
77	          z: this._toFinite(target.position.z, 0),
78	        },
79	        fov: this._toFinite(camera.fov, 64),
80	      },
81	      light: this._readLight(engine),
82	      background: this._readBackground(engine),
83	      earth: this._readTransform(engine, earthId),
84	      rocket: this._readRocket(engine),
85	      jetEngine: this._readJetEngine(engine),
86	      astronaut: this._readTransform(engine, astronautId),
87	      terrian: this._readTransform(engine, terrianId),
88	    };
89	  }
90	
91	  private _readRocket(engine: Engine): MainRocketState {
92	    const transform = this._readTransform(engine, rocketId);
93	    const defaults = DEFAULT_MAIN_SCENE_STATE.rocket;
94	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
95	    return {
96	      ...transform,
97	      flame: rocket?.getFlameState() ?? defaults.flame,
98	    };
99	  }
100	
101	  private _applyRocket(engine: Engine, state: MainRocketState): void {
102	    const rocket = engine.getSceneObjectById(rocketId) as MainRocketPort | null;
103	    if (!rocket) return;
104	    rocket.setFlameState(state.flame);
105	  }
106	
107	  private _applyJetEngine(engine: Engine, state: MainJetEngineState): void {
108	    const jet = engine.getSceneObjectById(jetEngineId) as SceneObject<
109	      JetEngineTweenProps
110	    > | null;
111	    if (!jet || typeof jet.setTimelineVars !== "function") return;
112	    const { position: _p, rotation: _r, scale: _s, ...rest } = state;
113	    jet.setTimelineVars(rest, "to");
114	  }
115	
116	  private _readJetEngine(engine: Engine): MainJetEngineState {
117	    const transform = this._readTransform(engine, jetEngineId);
118	    const defaults = DEFAULT_MAIN_SCENE_STATE.jetEngine;
119	    const object = engine.getSceneObjectById(jetEngineId) as
120	      | { getRuntimeOptions?: () => Record<string, unknown> }
121	      | null;
122	    const runtime = object?.getRuntimeOptions?.() ?? {};
123	    return {
124	      ...transform,
125	      intensity: this._toFinite(runtime.intensity, defaults.intensity),
126	      length: this._toFinite(runtime.length, defaults.length),
127	      nozzleRadius: this._toFinite(runtime.nozzleRadius, defaults.nozzleRadius),
128	      nozzleGap: this._toFinite(runtime.nozzleGap, defaults.nozzleGap),
129	      noise: this._toFinite(runtime.noise, defaults.noise),
130	      bloom: this._toFinite(runtime.bloom, defaults.bloom),
131	    };
132	  }
133	
134	  private _applyLight(engine: Engine, state: AboutLightState): void {
135	    const light = engine.getSceneObjectById(
136	      aboutLightsId,
137	    ) as AboutLightsPort | null;
138	    if (!light) return;
139	    light.setState(state);
140	  }
141	
142	  private _readLight(engine: Engine): AboutLightState {
143	    const light = engine.getSceneObjectById(
144	      aboutLightsId,
145	    ) as AboutLightsPort | null;
146	    if (!light) {
147	      return {
148	        visible: ABOUT_DEFAULT_SCENE_STATE.light.visible,
149	        rig: {
150	          position: { ...ABOUT_DEFAULT_SCENE_STATE.light.rig.position },
151	          rotation: { ...ABOUT_DEFAULT_SCENE_STATE.light.rig.rotation },
152	          scale: { ...ABOUT_DEFAULT_SCENE_STATE.light.rig.scale },
153	          visible: ABOUT_DEFAULT_SCENE_STATE.light.rig.visible,
154	        },
155	        travelProgress: ABOUT_DEFAULT_SCENE_STATE.light.travelProgress,
156	        intensity: ABOUT_DEFAULT_SCENE_STATE.light.intensity,
157	        ambientLight: ABOUT_DEFAULT_SCENE_STATE.light.ambientLight,
158	        keyLight: ABOUT_DEFAULT_SCENE_STATE.light.keyLight,
159	        fillLight: ABOUT_DEFAULT_SCENE_STATE.light.fillLight,
160	        rimLight: ABOUT_DEFAULT_SCENE_STATE.light.rimLight,
161	      };
162	    }
163	    return light.getState();
164	  }
165	
166	  private _readTransform(engine: Engine, id: string): AboutTransformState {
167	    const target = engine.getObjectById(id) as THREE.Object3D | null;
168	    const rotation = Helpers.readRotationDeg(target);
169	    const defaults = this._resolveTransformDefaults(id);
170	    return {
171	      position: {
172	        x: this._toFinite(target?.position.x, defaults.position.x),
173	        y: this._toFinite(target?.position.y, defaults.position.y),
174	        z: this._toFinite(target?.position.z, defaults.position.z),
175	      },
176	      rotation: {
177	        x: this._toFinite(rotation.x, defaults.rotation.x),
178	        y: this._toFinite(rotation.y, defaults.rotation.y),
179	        z: this._toFinite(rotation.z, defaults.rotation.z),
180	      },
181	      scale: {
182	        x: this._toFinite(target?.scale.x, defaults.scale.x),
183	        y: this._toFinite(target?.scale.y, defaults.scale.y),
184	        z: this._toFinite(target?.scale.z, defaults.scale.z),
185	      },
186	      visible: target?.visible ?? defaults.visible,
187	    };
188	  }
189	
190	  private _readBackground(engine: Engine): AboutBackgroundState {
191	    const defaults = ABOUT_DEFAULT_SCENE_STATE.background;
192	    const transform = this._readTransform(engine, aboutBackgroundId);
193	    const object = engine.getSceneObjectById(aboutBackgroundId) as
194	      | { getRuntimeOptions?: () => Record<string, unknown> }
195	      | null;
196	    const runtimeOptions = object?.getRuntimeOptions?.() ?? {};
197	    const look = runtimeOptions.look as Record<string, unknown> | undefined;
198	    return {
199	      ...transform,
200	      exposure: this._toFinite(runtimeOptions.exposure, defaults.exposure),
201	      look: {
202	        topColor: this._toFinite(look?.topColor, defaults.look.topColor),
203	        bottomColor: this._toFinite(
204	          look?.bottomColor,
205	          defaults.look.bottomColor,
206	        ),
207	        accentColor: this._toFinite(
208	          look?.accentColor,
209	          defaults.look.accentColor,
210	        ),
211	        starIntensity: this._toFinite(
212	          look?.starIntensity,
213	          defaults.look.starIntensity,
214	        ),
215	        starDensity: this._toFinite(
216	          look?.starDensity,
217	          defaults.look.starDensity,
218	        ),
219	        nebulaStrength: this._toFinite(
220	          look?.nebulaStrength,
221	          defaults.look.nebulaStrength,
222	        ),
223	        motionStrength: this._toFinite(
224	          look?.motionStrength,
225	          defaults.look.motionStrength,
226	        ),
227	        legacyMix: this._toFinite(look?.legacyMix, defaults.look.legacyMix),
228	      },
229	    };
230	  }
231	
232	  private _resolveTransformDefaults(id: string): AboutTransformState {
233	    if (id === earthId) return ABOUT_DEFAULT_SCENE_STATE.earth;
234	    if (id === rocketId) {
235	      const r = ABOUT_DEFAULT_SCENE_STATE.rocket;
236	      return {
237	        position: { ...r.position },
238	        rotation: { ...r.rotation },
239	        scale: { ...r.scale },
240	        visible: r.visible,
241	      };
242	    }
243	    if (id === jetEngineId) {
244	      const j = ABOUT_DEFAULT_SCENE_STATE.jetEngine;
245	      return {
246	        position: { ...j.position },
247	        rotation: { ...j.rotation },
248	        scale: { ...j.scale },
249	        visible: j.visible,
250	      };
251	    }
252	    if (id === astronautId) return ABOUT_DEFAULT_SCENE_STATE.astronaut;
253	    if (id === terrianId) return ABOUT_DEFAULT_SCENE_STATE.terrian;
254	    return ABOUT_DEFAULT_SCENE_STATE.background;
255	  }
256	
257	  private _toFinite(value: unknown, fallback: number): number {
258	    if (typeof value !== "number") return fallback;
259	    if (!Number.isFinite(value)) return fallback;
260	    return value;
261	  }
262	}
