49	const LEGACY_ABOUT_SHEET_ID_MAP = {
50	  whoIntro: "who",
51	  servicesIntro: "missionVision",
52	  servicesDesc: "services",
53	  clientIntro: "client",
54	  clientEnd: "contact",
55	} as const satisfies Readonly<Record<string, AboutTheatreSheetId>>;
56	type LegacyAboutSheetId = keyof typeof LEGACY_ABOUT_SHEET_ID_MAP;
57	const CLASS = "AboutTheatreRuntime";
58	const DEBUG_SCENE_KEYS: readonly AboutSceneSectionKey[] = ["contact"];
59	const DEBUG_SHEET_IDS: readonly AboutTheatreSheetId[] = ["contact"];
60	const DEBUG_PROGRESS_BUCKETS = 20;
61	const debugResolveLogKeyByScene = new Map<AboutSceneSectionKey, string>();
62	const debugSyncLogKeyByScene = new Map<AboutSceneSectionKey, string>();
63	
64	function resolveDebugProgressBucket(progress: number): number {
65	  return Math.max(
66	    0,
67	    Math.min(
68	      DEBUG_PROGRESS_BUCKETS,
69	      Math.round(Math.max(0, Math.min(1, progress)) * DEBUG_PROGRESS_BUCKETS),
70	    ),
71	  );
72	}
73	
74	function shouldLogDebugBucket(
75	  map: Map<AboutSceneSectionKey, string>,
76	  sceneKey: AboutSceneSectionKey,
77	  phase: string,
78	  progress: number,
79	  sheetId?: AboutTheatreSheetId | null,
80	): boolean {
81	  const bucket = resolveDebugProgressBucket(progress);
82	  const nextKey = `${phase}:${sheetId ?? "none"}:${bucket}`;
83	  const previousKey = map.get(sceneKey) ?? null;
84	  if (previousKey === nextKey) return false;
85	  map.set(sceneKey, nextKey);
86	  return true;
87	}
