89	function normalizeAboutTheatreState(
90	  savedState: Record<string, unknown>,
91	): Record<string, unknown> {
92	  const migratedState = migrateLegacyAboutTheatreState(savedState);
93	  const sheetsById = readAboutRecord(migratedState.sheetsById);
94	  const cameraSheet = readAboutRecord(sheetsById?.heroIntro);
95	  const sequence = readAboutRecord(cameraSheet?.sequence);
96	  const staticOverrides = readAboutRecord(sequence?.staticOverrides);
97	  const objectsByKey = readAboutRecord(staticOverrides?.byObject);
98	  const cameraObject = readAboutRecord(objectsByKey?.[ABOUT_THEATRE_OBJECT_ID]);
99	
100	  if (cameraObject) {
101	    const mergedValues = mergeAboutSceneState(
102	      cameraObject as Partial<typeof ABOUT_DEFAULT_SCENE_STATE>,
103	    );
104	    Object.assign(cameraObject, pickAboutTheatreValue(mergedValues));
105	  }
106	
107	  const projectDefinition = readAboutRecord(
108	    migratedState.definitionVersion != null ? migratedState : null,
109	  );
110	  if (!projectDefinition || !projectDefinition.addressesBySheetId) {
111	    return migratedState;
112	  }
113	  return {
114	    ...migratedState,
115	    projectId: ABOUT_THEATRE_PROJECT_ID,
116	  };
117	}
118	
119	function migrateLegacyAboutTheatreState(
120	  savedState: Record<string, unknown>,
121	): Record<string, unknown> {
122	  const sheetsById = readAboutRecord(savedState.sheetsById);
123	  if (!sheetsById) {
124	    return savedState;
125	  }
126	  const nextSheetsById: Record<string, unknown> = {};
127	  let didChange = false;
128	
129	  Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
130	    const mappedSheetId =
131	      LEGACY_ABOUT_SHEET_ID_MAP[sheetId as LegacyAboutSheetId] ?? sheetId;
132	    if (mappedSheetId !== sheetId) {
133	      didChange = true;
134	    }
135	    if ((ABOUT_THEATRE_SHEET_IDS as readonly string[]).includes(mappedSheetId)) {
136	      nextSheetsById[mappedSheetId] = sheetState;
137	      return;
138	    }
139	    didChange = true;
140	  });
141	
142	  if (!didChange) {
143	    return savedState;
144	  }
145	
146	  return {
147	    ...savedState,
148	    sheetsById: nextSheetsById,
149	  };
150	}
151	
152	function readAboutRecord(value: unknown): Record<string, unknown> | null {
153	  if (value == null || typeof value !== "object" || Array.isArray(value)) {
154	    return null;
155	  }
156	  return value as Record<string, unknown>;
157	}
158	
159	function mergeAboutTheatreStateSources(
160	  fileState: Record<string, unknown> | null,
161	  savedState: Record<string, unknown> | null,
162	): Record<string, unknown> | null {
163	  if (!fileState) return savedState;
164	  if (!savedState) return fileState;
165	  const fileSheetsById = readAboutRecord(fileState.sheetsById) ?? {};
166	  const savedSheetsById = readAboutRecord(savedState.sheetsById) ?? {};
167	  return {
168	    ...fileState,
169	    ...savedState,
170	    sheetsById: {
171	      ...fileSheetsById,
172	      ...savedSheetsById,
173	    },
174	  };
175	}
