177	class AboutTheatreRuntime {
178	  private static _instance: AboutTheatreRuntime | null = null;
179	
180	  private readonly _rig = new AboutSceneRig();
181	  private readonly _stateSource: Record<string, unknown>;
182	  private readonly _project: TheatreProjectPort<
183	    AboutTheatreValue,
184	    AboutTheatreProps
185	  >;
186	  private readonly _objectBySheetId = new Map<
187	    AboutTheatreSheetId,
188	    AboutTheatreObject
189	  >();
190	  private readonly _sequenceBySheetId = new Map<
191	    AboutTheatreSheetId,
192	    TheatreSequencePort
193	  >();
194	  private readonly _lengthBySheetId = new Map<AboutTheatreSheetId, number>();
195	  private readonly _playbackRangeBySheetId = new Map<
196	    AboutTheatreSheetId,
197	    AboutTheatrePlaybackRange
198	  >();
199	  private readonly _autoplayRuntime: AboutTheatreAutoplayRuntime;
200	  private constructor() {
201	    this._autoplayRuntime = new AboutTheatreAutoplayRuntime(
202	      (engine, values) => this._rig.apply(engine, mergeAboutTheatreValue(values)),
203	    );
204	    this._stateSource = resolveAboutTheatreStateSource();
205	    this._project = TheatreProjectSession.open<
206	      AboutTheatreValue,
207	      AboutTheatreProps
208	    >(ABOUT_THEATRE_PROJECT_ID, { state: this._stateSource });
209	    ABOUT_THEATRE_SHEET_IDS.forEach((sheetId) => {
210	      const sheet = TheatreSheetSession.open(this._project, sheetId);
211	      const object = sheet.object(
212	        ABOUT_THEATRE_OBJECT_ID,
213	        pickAboutTheatreValue(mergeAboutSceneState()),
214	        {
215	          reconfigure: true,
216	        },
217	      );
218	      const sequenceLength = this._resolveSheetLength(sheetId, sheet.sequence);
219	      const playbackRange = this._resolvePreviewRange(sheetId, sequenceLength);
220	      this._objectBySheetId.set(sheetId, object);
221	      this._sequenceBySheetId.set(sheetId, sheet.sequence);
222	      this._lengthBySheetId.set(sheetId, sequenceLength);
223	      if (playbackRange) {
224	        this._playbackRangeBySheetId.set(sheetId, playbackRange);
225	      }
226	      if (DEBUG_SHEET_IDS.includes(sheetId)) {
227	        Logger.info(CLASS, "constructor", `Initialized ${sheetId} theatre sheet.`, {
228	          sheetId,
229	          sequenceLength,
230	          playbackRange,
231	          hasPreviewRange: playbackRange != null,
232	        });
233	      }
234	    });
235	  }
236	
237	  static getInstance(): AboutTheatreRuntime {
238	    if (AboutTheatreRuntime._instance) return AboutTheatreRuntime._instance;
239	    AboutTheatreRuntime._instance = new AboutTheatreRuntime();
240	    return AboutTheatreRuntime._instance;
241	  }
242	
243	  readState(sheetId: AboutTheatreSheetId, position = 0): AboutTheatreValue {
244	    const sequence = this._sequenceBySheetId.get(sheetId);
245	    const object = this._objectBySheetId.get(sheetId);
246	    if (!sequence || !object)
247	      return pickAboutTheatreValue(cloneAboutSceneState(ABOUT_DEFAULT_SCENE_STATE));
248	    const previousPosition = sequence.position;
249	    sequence.position = this._clampPosition(
250	      position,
251	      this._lengthBySheetId.get(sheetId) ?? 0,
252	    );
253	    const state = mergeAboutTheatreValue(object.value);
254	    sequence.position = previousPosition;
255	    return pickAboutTheatreValue(state);
256	  }
257	
258	  resolveSceneProgressState(
259	    sceneKey: AboutSceneSectionKey,
260	    progress: number,
261	  ): AboutSceneProgressState | null {
262	    const resolvedSteps = this._resolveSceneSteps(sceneKey)
263	      .map((step) => this._resolveStep(step))
264	      .filter((step): step is AboutResolvedTheatrePlaybackStep => step != null);
265	    if (resolvedSteps.length === 0) {
266	      if (DEBUG_SCENE_KEYS.includes(sceneKey)) {
267	        Logger.warn(CLASS, "resolveSceneProgressState", "No theatre steps resolved.", {
268	          sceneKey,
269	          progress,
270	        });
271	      }
272	      return null;
273	    }
274	    const clampedProgress = this._clampPosition(progress, 1);
275	    for (const step of resolvedSteps) {
276	      if (!this._isProgressWithinRange(clampedProgress, step.progressRange)) {
277	        continue;
278	      }
279	      const nextState = {
280	        sheetId: step.sheetId,
281	        localProgress: this._resolveLocalProgress(
282	          clampedProgress,
283	          step.progressRange,
284	        ),
285	      };
286	      if (
287	        DEBUG_SCENE_KEYS.includes(sceneKey) &&
288	        shouldLogDebugBucket(
289	          debugResolveLogKeyByScene,
290	          sceneKey,
291	          "resolve",
292	          progress,
293	          nextState.sheetId,
294	        )
295	      ) {
296	        Logger.info(
297	          CLASS,
298	          "resolveSceneProgressState",
299	          `Resolved theatre progress for ${sceneKey}.`,
300	          {
301	            sceneKey,
302	            progress,
303	            clampedProgress,
304	            resolvedStep: step,
305	            nextState,
306	          },
307	        );
308	      }
309	      return nextState;
310	    }
311	    if (
312	      DEBUG_SCENE_KEYS.includes(sceneKey) &&
313	      shouldLogDebugBucket(
314	        debugResolveLogKeyByScene,
315	        sceneKey,
316	        "resolve-miss",
317	        progress,
318	      )
319	    ) {
320	      Logger.warn(
321	        CLASS,
322	        "resolveSceneProgressState",
323	        "Resolved steps exist but none matched current progress.",
324	        {
325	          sceneKey,
326	          progress,
327	          clampedProgress,
328	          resolvedSteps,
329	        },
330	      );
331	    }
332	    return null;
333	  }
334	
335	  resolveSceneState(
336	    sceneKey: AboutSceneSectionKey,
337	    progress: number,
338	  ): AboutTheatreValue | null {
339	    const state = this.resolveSceneProgressState(sceneKey, progress);
340	    if (!state) return null;
341	    const range = this._resolvePlaybackRange(
342	      state.sheetId,
343	      this._lengthBySheetId.get(state.sheetId) ?? 0,
344	    );
345	    const position =
346	      range.start +
347	      (range.end - range.start) * this._clampPosition(state.localProgress, 1);
348	    return this.readState(state.sheetId, position);
349	  }
350	
351	  startPreview(engine: Engine): Promise<void> {
352	    return this._autoplayRuntime.startPreview(
353	      engine,
