584	  private _resolvePreviewRange(
585	    sheetId: AboutTheatreSheetId,
586	    sheetLength: number,
587	  ): AboutTheatrePlaybackRange | null {
588	    const tracksByObject = this._readSheetTracksByObject(sheetId);
589	    const objectTracks = tracksByObject?.[ABOUT_THEATRE_OBJECT_ID];
590	    if (!objectTracks || typeof objectTracks !== "object") return null;
591	    const trackData = (objectTracks as Record<string, unknown>).trackData;
592	    if (!trackData || typeof trackData !== "object") return null;
593	    let minPosition = Number.POSITIVE_INFINITY;
594	    let maxPosition = Number.NEGATIVE_INFINITY;
595	    Object.values(trackData as Record<string, unknown>).forEach(
596	      (trackState) => {
597	        if (!trackState || typeof trackState !== "object") return;
598	        const keyframes = (trackState as Record<string, unknown>).keyframes;
599	        if (!Array.isArray(keyframes)) return;
600	        const positionedKeyframes = keyframes
601	          .map((keyframe) => {
602	            if (!keyframe || typeof keyframe !== "object") return null;
603	            const position = (keyframe as Record<string, unknown>).position;
604	            return typeof position === "number" ? position : null;
605	          })
606	          .filter(
607	            (position): position is number =>
608	              typeof position === "number" && Number.isFinite(position),
609	          );
610	        if (positionedKeyframes.length < 2) return;
611	        minPosition = Math.min(minPosition, ...positionedKeyframes);
612	        maxPosition = Math.max(maxPosition, ...positionedKeyframes);
613	      },
614	    );
615	    if (!Number.isFinite(minPosition) || !Number.isFinite(maxPosition)) {
616	      return null;
617	    }
618	    if (maxPosition <= minPosition) {
619	      return null;
620	    }
621	    return {
622	      start: this._clampPosition(minPosition, sheetLength),
623	      end: this._clampPosition(maxPosition, sheetLength),
624	    };
625	  }
626	
627	  private _readSheetTracksByObject(
628	    sheetId: AboutTheatreSheetId,
629	  ): Record<string, unknown> | null {
630	    const sheetsById = readAboutRecord(this._stateSource.sheetsById);
631	    if (!sheetsById) return null;
632	    const sheetState = readAboutRecord(sheetsById[sheetId]);
633	    if (!sheetState) return null;
634	    const sequence = readAboutRecord(sheetState.sequence);
635	    if (!sequence) return null;
636	    const tracksByObject = readAboutRecord(sequence.tracksByObject);
637	    if (!tracksByObject) return null;
638	    return tracksByObject;
639	  }
