257	  private _drawDot(info: BallInfo): void {
258	    info.sphere.scale.x += info.radiusDeincrement;
259	    info.sphere.scale.y += info.radiusDeincrement;
260	    info.sphere.scale.z += info.radiusDeincrement;
261	    info.startX += info.vx * 0.6;
262	    info.startY -= info.vy * 0.5;
263	    info.startZ -= info.vz * 0.6;
264	    info.sphere.position.x = info.startX;
265	    info.sphere.position.y = info.startY;
266	    info.sphere.position.z = info.startZ;
267	
268	    if (
269	      info.sphere.position.y <
270	      GravityBalls.FLOOR_LEVEL - info.radiusStart / 2
271	    ) {
272	      if (!info.bounced) {
273	        info.vx *= info.vxMult;
