295	      info.bounced = true;
296	    }
297	
298	    info.vy += info.gravity;
299	
300	    if (info.sphere.scale.y <= 0.1) {
301	      this._spheresInfo.delete(info.ID);
302	      info.sphere.parent?.remove(info.sphere);
303	      info.sphere.geometry.dispose();
304	      info.sphere.material.dispose();
305	    }
306	  }
