308	  private _clearAllSpheres(): void {
309	    for (const info of this._spheresInfo.values()) {
310	      info.sphere.parent?.remove(info.sphere);
311	      info.sphere.geometry.dispose();
312	      info.sphere.material.dispose();
313	    }
314	    this._spheresInfo.clear();
